/bin/zsh -lc "python3 -B -c 'from itertools import permutations; c=[3,2,4]; a=[(1,2,1),(2,3,2),(1,3,1)];
for p in permutations(range(3)):
    rem=c.copy(); ans=0
    for k in p:
        l,r,d=a[k]
        if any(rem[i]<d for i in range(l-1,r)):
            ans=k+1; break
        for i in range(l-1,r): rem[i]-=d
    print(\"order\", tuple(k+1 for k in p), \"answer\", ans)'"

